import { KnowledgeRepository } from "../topology/KnowledgeRepository.js";
import { TopologyModel, } from "../topology/TopologyModel.js";
import { createDefaultSignalPolicy, } from "../topology/SignalPolicy.js";
import { prepareTopologyRenderFrame, } from "../topology/renderPipeline.js";
import { resolveRelationshipContext, } from "../topology/relationshipContext.js";
import { WorldModel } from "../topology/worldModel.js";
const ALLOWED_RELATIONSHIP_KINDS = new Set([
    "related",
    "parent",
    "child",
    "references",
    "mentions",
    "depends-on",
    "supports",
    "contains",
    "custom",
]);
function normalizeRelationshipKind(kind) {
    if (!kind)
        return undefined;
    const normalized = kind.trim().toLowerCase();
    return ALLOWED_RELATIONSHIP_KINDS.has(normalized)
        ? normalized
        : "custom";
}
export function inspectOperationalTopologyDefinition(definition) {
    const issues = [];
    const { grid, entities = [], relationships = [] } = definition;
    if (!Number.isFinite(grid.radius) ||
        grid.radius <= 0 ||
        !Number.isInteger(grid.columns) ||
        grid.columns <= 0 ||
        !Number.isInteger(grid.rows) ||
        grid.rows <= 0) {
        issues.push({
            type: "invalid-grid",
            message: "Grid radius must be positive and columns/rows must be positive integers.",
        });
    }
    const entityIds = new Set();
    for (const entity of entities) {
        if (entityIds.has(entity.id)) {
            issues.push({
                type: "duplicate-entity",
                message: `Duplicate entity id: ${entity.id}`,
                entityId: entity.id,
            });
            continue;
        }
        entityIds.add(entity.id);
    }
    for (const relationship of relationships) {
        if (!entityIds.has(relationship.from) ||
            !entityIds.has(relationship.to)) {
            issues.push({
                type: "broken-relationship",
                message: `Broken relationship: ${relationship.from} -> ${relationship.to}`,
                relationship,
            });
        }
    }
    return issues;
}
export function createOperationalTopology(definition) {
    const issues = inspectOperationalTopologyDefinition(definition);
    if (issues.length > 0) {
        throw new TypeError(`Invalid operational topology:\n${issues
            .map((issue) => `- ${issue.message}`)
            .join("\n")}`);
    }
    const entities = [...(definition.entities ?? [])];
    const relationships = [...(definition.relationships ?? [])];
    const model = new TopologyModel({
        ...definition.grid,
        entities,
        relationships,
    });
    const world = new WorldModel({
        radius: model.radius,
        cells: model.cells,
        entities,
        relationships,
    });
    const repository = new KnowledgeRepository({
        entities: entities.map((entity) => ({
            id: entity.id,
            label: entity.label,
            subtitle: entity.subtitle,
            q: entity.q,
            r: entity.r,
            metadata: {
                image: entity.image,
                imageOffsetY: entity.imageOffsetY,
                variant: entity.variant,
                size: entity.size,
            },
        })),
        relationships: relationships.map((relationship) => ({
            from: relationship.from,
            to: relationship.to,
            kind: normalizeRelationshipKind(relationship.kind),
            active: relationship.active,
            muted: relationship.muted,
        })),
    });
    const signalPolicy = createDefaultSignalPolicy(definition.signal);
    const entityMap = new Map(entities.map((entity) => [entity.id, entity]));
    return {
        model,
        world,
        repository,
        signalPolicy,
        getEntity(id) {
            return entityMap.get(id) ?? null;
        },
        getRelationshipContext(entityId) {
            return resolveRelationshipContext(entityId, relationships);
        },
        createRenderFrame(options = {}) {
            return prepareTopologyRenderFrame({
                ...options,
                cells: options.cells ?? model.cells,
                occupants: entities,
                relationships,
            });
        },
    };
}
